var e=JSON.parse(`[{"id":"dl-bavette-brocoli-patate-douce-graines-courge","name":"Bavette poêlée, plaque de brocoli et patate douce rôtis, yaourt aux graines de courge","description":"Une grande assiette d’automne : bavette saisie saignante, brocoli et patate douce caramélisés au four, sauce yaourt-persil généreuse en graines de courge torréfiées.","emoji":"🥩","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":30,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"boeuf-bavette","qty":320,"unit":"g"},{"id":"brocoli","qty":1,"unit":"piece","note":"en fleurettes, tige pelée en bâtonnets"},{"id":"patate-douce","qty":1,"unit":"piece","note":"en quartiers avec la peau"},{"id":"oignon-rouge","qty":1,"unit":"piece","note":"en quartiers"},{"id":"huile-olive","qty":30,"unit":"ml"},{"id":"yaourt-grec","qty":150,"unit":"g"},{"id":"graines-courge","qty":30,"unit":"g"},{"id":"persil","qty":20,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"ail","qty":1,"unit":"gousse"},{"id":"paprika","qty":1,"unit":"cac"},{"id":"beurre","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 220 °C. Sortez la bavette du réfrigérateur 20 min avant la cuisson et salez-la.","Sur une grande plaque, mélangez la patate douce, l’oignon rouge, 20 ml d’huile d’olive, le paprika et du sel. Enfournez 15 min.","Ajoutez le brocoli huilé (10 ml) sur la plaque et poursuivez 15 min : les fleurettes doivent être grillées sur les bords et la patate douce tendre sous la pointe du couteau.","Pendant ce temps, torréfiez les graines de courge à sec dans une poêle 3 min à feu moyen jusqu’à ce qu’elles gonflent et crépitent. Mélangez le yaourt, le persil haché, l’ail râpé, le zeste et le jus d’un demi-citron, puis la moitié des graines.","Dans la même poêle très chaude, saisissez la bavette avec le beurre 2 à 3 min par face pour une cuisson saignante. Laissez reposer 5 min sous une feuille de papier, puis tranchez finement contre les fibres.","Dressez les légumes rôtis, la viande tranchée, la sauce yaourt et le reste des graines. Arrosez du jus de l’autre demi-citron."],"tags":["four","riche en protéines","sportif","rapide"],"seasons":["automne","hiver"],"technique":"roti","flavors":["grille","herbace","cremeux"],"tips":"Les restes de légumes rôtis et de sauce font une excellente lunch box froide."},{"id":"dl-boeuf-braise-fenouil-artichauts-polenta","name":"Paleron braisé au fenouil, artichauts et olives, polenta au parmesan","description":"Un braisé à l’italienne où le fenouil et les cœurs d’artichaut fondent dans le jus de bœuf au vin blanc et aux olives, servi sur une polenta crémeuse au parmesan.","emoji":"🍲","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":25,"cookTime":150,"difficulty":"facile","servings":4,"ingredients":[{"id":"boeuf-paleron","qty":800,"unit":"g","note":"en gros cubes"},{"id":"fenouil","qty":2,"unit":"piece","note":"en quartiers"},{"id":"artichaut","qty":4,"unit":"piece","note":"cœurs parés ou 400 g de cœurs surgelés"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"vin-blanc","qty":200,"unit":"ml"},{"id":"bouillon-boeuf","qty":300,"unit":"ml"},{"id":"olive","qty":40,"unit":"g","note":"noires"},{"id":"huile-olive","qty":30,"unit":"ml"},{"id":"polenta","qty":200,"unit":"g"},{"id":"parmesan","qty":60,"unit":"g"},{"id":"beurre","qty":20,"unit":"g"},{"id":"graines-fenouil","qty":1,"unit":"cac"},{"id":"romarin","qty":1,"unit":"brin"},{"id":"persil","qty":15,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Épongez et salez le bœuf. Dans une cocotte, chauffez l’huile à feu vif et saisissez la viande en 2 fournées, 4 min chacune, jusqu’à une croûte brune. Réservez.","À feu moyen, faites suer l’oignon émincé 5 min, ajoutez l’ail, les graines de fenouil et le romarin 1 min. Déglacez au vin blanc en grattant le fond, laissez réduire de moitié 3 min.","Remettez le bœuf, ajoutez les tomates et le bouillon. Couvrez et laissez mijoter 1 h 30 à feu très doux (ou au four à 150 °C).","Ajoutez le fenouil, les artichauts et les olives, enfoncez-les dans le jus et poursuivez 45 min à couvert : la viande doit se défaire à la fourchette et le fenouil être fondant.","Pour la polenta, portez 1 l d’eau salée à ébullition, versez la polenta en pluie en fouettant, puis cuisez 10 min à feu doux en remuant (5 min pour une polenta instantanée). Hors du feu, ajoutez beurre et parmesan.","Rectifiez l’assaisonnement du braisé, parsemez de persil et servez sur la polenta."],"tags":["mijoté","week-end","batch cooking","réconfortant","riche en protéines"],"seasons":["printemps","automne"],"technique":"braise","flavors":["umami","herbace","reconfortant"],"tips":"Encore meilleur le lendemain ; se congèle sans la polenta."},{"id":"dl-biftekia-feta-fasolakia","name":"Biftekia farcis à la feta, fasolakia aux tomates et pommes de terre","description":"Steaks hachés grecs à l’origan au cœur de feta fondante, servis avec des haricots verts mijotés à l’huile d’olive et à la tomate, comme dans les tavernes.","emoji":"🍔","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":20,"cookTime":45,"difficulty":"facile","servings":2,"ingredients":[{"id":"boeuf-hache","qty":300,"unit":"g"},{"id":"feta","qty":80,"unit":"g"},{"id":"oignon","qty":1,"unit":"piece","note":"moitié râpée pour la viande, moitié émincée"},{"id":"origan","qty":1,"unit":"cac"},{"id":"menthe","qty":10,"unit":"g"},{"id":"haricots-verts","qty":400,"unit":"g"},{"id":"tomates-concassees","qty":300,"unit":"g"},{"id":"pomme-de-terre","qty":300,"unit":"g","note":"en gros cubes"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"huile-olive","qty":40,"unit":"ml"},{"id":"persil","qty":15,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Dans une sauteuse, chauffez 30 ml d’huile à feu moyen, faites suer l’oignon émincé et l’ail 4 min. Ajoutez les haricots verts équeutés, les pommes de terre, les tomates et 150 ml d’eau. Salez.","Couvrez et laissez mijoter 35 min à feu doux en remuant de temps en temps : les haricots doivent être très tendres et la sauce nappante.","Pendant ce temps, mélangez le bœuf avec l’oignon râpé, l’origan, la menthe hachée, du sel et du poivre. Formez 4 galettes, posez un bâtonnet de feta (20 g) au centre de chacune et refermez la viande autour.","Cuisez les biftekia dans une poêle avec 10 ml d’huile à feu moyen-vif, 4 min par face : la croûte doit être brune et la feta commencer à couler.","Servez les biftekia sur les fasolakia, parsemez de persil et accompagnez de quartiers de citron."],"tags":["familial","riche en protéines","économique","une poêle"],"seasons":["ete","automne"],"technique":"poele","flavors":["herbace","acidule","umami"]},{"id":"dl-salade-rosbif-lentilles-poire-roquefort","name":"Salade-repas de rosbif, lentilles beluga, poire, roquefort et noix","description":"Lentilles beluga tièdes, fines tranches de rôti de bœuf rosé, poire juteuse, roquette poivrée, roquefort et cerneaux de noix, vinaigrette à l’beurre clarifié.","emoji":"🥗","category":"salade-composee","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"boeuf-rosbif","qty":280,"unit":"g"},{"id":"lentilles-vertes","qty":120,"unit":"g","note":"beluga ou du Puy"},{"id":"poire","qty":1,"unit":"piece"},{"id":"roquette","qty":100,"unit":"g"},{"id":"endive","qty":2,"unit":"piece","note":"ou trévise"},{"id":"roquefort","qty":50,"unit":"g"},{"id":"noix","qty":30,"unit":"g"},{"id":"echalote","qty":1,"unit":"piece"},{"id":"huile-noix","qty":2,"unit":"cac","note":"en assaisonnement, hors du feu"},{"id":"huile-olive","qty":15,"unit":"ml"},{"id":"vinaigre-cidre","qty":15,"unit":"ml","note":"de Xérès"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"thym","qty":2,"unit":"brin"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : faites tremper les lentilles 12 h (une nuit) dans de l’eau tiède, jetez l’eau et rincez avant de cuire.","Rincez les lentilles et cuisez-les 20 à 25 min dans 3 fois leur volume d’eau frémissante avec le thym, sans sel. Elles doivent être tendres mais entières. Égouttez et salez.","Salez le rôti de bœuf. Saisissez-le dans une poêle avec l’huile d’olive à feu vif 2 à 3 min par face, puis enfournez 10 min à 200 °C pour un cœur rosé. Laissez reposer 10 min et tranchez finement.","Fouettez la moutarde, le vinaigre, l’échalote ciselée et l’beurre clarifié. Versez la moitié sur les lentilles tièdes.","Torréfiez les noix 3 min à sec dans une poêle. Coupez la poire en lamelles et les endives en tronçons.","Dressez roquette et endives, les lentilles, la poire, le bœuf et le roquefort émietté. Arrosez du reste de vinaigrette et parsemez de noix.","Hors du feu, arrosez d’un filet d’huile de noix (1 c. à café par personne) pour le parfum."],"tags":["repas froid","lunch box","riche en protéines","préparation à l’avance"],"seasons":["automne","hiver"],"technique":"roti","flavors":["fruite","umami","acidule"],"restTime":720},{"id":"dl-steak-asperges-petits-pois-grenailles","name":"Rumsteck, asperges vertes, petits pois et grenailles au beurre d’herbes","description":"Le printemps dans l’assiette : rumsteck saisi, asperges vertes rôties, petits pois minute à la menthe et grenailles, le tout nappé d’un beurre aux herbes et citron.","emoji":"🌱","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"boeuf-steak","qty":2,"unit":"piece","note":"rumsteck de 180 g"},{"id":"asperge","qty":12,"unit":"piece","note":"vertes"},{"id":"petits-pois","qty":250,"unit":"g"},{"id":"pomme-de-terre","qty":350,"unit":"g","note":"grenailles"},{"id":"beurre","qty":30,"unit":"g"},{"id":"huile-olive","qty":15,"unit":"ml"},{"id":"ciboulette","qty":10,"unit":"g"},{"id":"menthe","qty":10,"unit":"g"},{"id":"estragon","qty":5,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"oignon-nouveau","qty":2,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez les grenailles entières 18 min à l’eau bouillante salée : la pointe du couteau doit s’enfoncer sans résistance. Égouttez et coupez-les en deux.","Écrasez le beurre avec la ciboulette, la menthe et l’estragon hachés et le zeste du citron. Réservez au frais.","Cassez la base dure des asperges. Faites-les rôtir dans une grande poêle avec l’huile 6 à 8 min à feu moyen-vif en les roulant : elles doivent être tendres et marquées.","Dans une casserole, faites suer les oignons nouveaux émincés 2 min avec une noix de beurre aux herbes, ajoutez les petits pois et 50 ml d’eau, cuisez 4 min à couvert.","Saisissez les steaks salés dans une poêle fumante 2 à 3 min par face, puis laissez reposer 4 min.","Dressez la viande, les légumes et les grenailles ; posez le reste du beurre d’herbes sur la viande chaude et arrosez d’un trait de jus de citron."],"tags":["rapide","riche en protéines","sportif"],"seasons":["printemps"],"technique":"poele","flavors":["herbace","frais","grille"]},{"id":"dl-escalopes-veau-courgettes-quinoa-pignons","name":"Escalopes de veau au citron, courgettes et haricots verts, quinoa aux pignons","description":"Escalopes de veau dorées minute au beurre citronné, poêlée estivale de courgettes et haricots verts au basilic et quinoa aux pignons grillés et au parmesan.","emoji":"🍋","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":15,"cookTime":25,"difficulty":"facile","servings":2,"ingredients":[{"id":"veau-escalope","qty":3,"unit":"piece"},{"id":"courgette","qty":2,"unit":"piece"},{"id":"haricots-verts","qty":200,"unit":"g"},{"id":"quinoa","qty":120,"unit":"g"},{"id":"pignons","qty":20,"unit":"g"},{"id":"parmesan","qty":30,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"beurre","qty":25,"unit":"g"},{"id":"huile-olive","qty":20,"unit":"ml"},{"id":"farine","qty":1,"unit":"cas"},{"id":"basilic","qty":15,"unit":"g"},{"id":"ail","qty":1,"unit":"gousse"},{"id":"vin-blanc","qty":60,"unit":"ml"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : rincez énergiquement le quinoa (3 eaux), puis faites-le tremper 12 h (une nuit) avec 1 c. à soupe de jus de citron ; rincez de nouveau avant de cuire.","Rincez le quinoa et cuisez-le 14 min dans 2,5 fois son volume d’eau salée, puis laissez gonfler 5 min hors du feu à couvert.","Cuisez les haricots verts 6 min à l’eau bouillante salée et rafraîchissez-les. Coupez les courgettes en demi-rondelles.","Faites sauter les courgettes dans l’huile d’olive à feu vif 5 min, ajoutez les haricots et l’ail haché 2 min. Hors du feu, ajoutez le basilic ciselé.","Torréfiez les pignons à sec 2 min jusqu’à ce qu’ils blondissent ; mélangez-les au quinoa avec le parmesan râpé.","Aplatissez les escalopes, salez et farinez-les légèrement. Faites-les dorer dans le beurre mousseux 1 min 30 par face à feu vif. Déglacez au vin blanc et au jus du citron, laissez réduire 1 min en nappant la viande.","Servez les escalopes nappées de leur jus avec la poêlée et le quinoa."],"tags":["rapide","une poêle","riche en protéines","léger","préparation à l’avance"],"seasons":["ete"],"technique":"poele","flavors":["acidule","herbace"],"restTime":720},{"id":"dl-agneau-butternut-pois-chiches-zaatar","name":"Épaule d’agneau rôtie, butternut et pois chiches au zaatar, yaourt à la grenade","description":"Épaule d’agneau désossée rôtie au cumin sur un lit de butternut et de pois chiches croustillants, servie avec un yaourt épais, du zaatar et des grains de grenade.","emoji":"🍖","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"levantine","prepTime":20,"cookTime":75,"difficulty":"facile","servings":4,"ingredients":[{"id":"agneau-epaule","qty":650,"unit":"g","note":"désossée, en gros morceaux"},{"id":"courge-butternut","qty":1000,"unit":"g","note":"en cubes avec la peau"},{"id":"pois-chiches","qty":400,"unit":"g","note":"égouttés"},{"id":"oignon-rouge","qty":2,"unit":"piece"},{"id":"ail","qty":4,"unit":"gousse"},{"id":"huile-olive","qty":30,"unit":"ml"},{"id":"cumin","qty":2,"unit":"cac"},{"id":"zaatar","qty":2,"unit":"cas"},{"id":"yaourt-grec","qty":300,"unit":"g"},{"id":"grenade","qty":1,"unit":"piece"},{"id":"persil","qty":30,"unit":"g"},{"id":"menthe","qty":15,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"pain-pita","qty":2,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Frottez l’agneau avec 15 ml d’huile, le cumin, l’ail écrasé et du sel. Laissez reposer 20 min à température ambiante. Préchauffez le four à 200 °C.","Dans un grand plat, mélangez la butternut, les oignons rouges en quartiers, les pois chiches bien séchés, le reste d’huile et 1 cuillère de zaatar. Posez l’agneau par-dessus.","Enfournez 30 min, puis baissez à 180 °C et poursuivez 45 min en retournant les légumes à mi-cuisson : la courge doit être fondante et caramélisée, les pois chiches croustillants, l’agneau doré et tendre.","Mélangez le yaourt avec le jus d’un demi-citron et une pincée de sel. Égrenez la grenade.","Laissez reposer la viande 10 min, puis effilochez-la ou tranchez-la. Réchauffez les pitas 2 min au four.","Servez l’agneau sur les légumes, avec le yaourt, le reste du zaatar, les herbes hachées et la grenade."],"tags":["four","week-end","familial","riche en protéines"],"seasons":["automne","hiver"],"technique":"roti","flavors":["epice","fruite","herbace"]},{"id":"dl-cotelettes-agneau-vignarola","name":"Côtelettes d’agneau grillées et vignarola de fèves, petits pois et artichauts","description":"La vignarola romaine, ragoût printanier de fèves, petits pois, artichauts et laitue au guanciale, sous des côtelettes d’agneau grillées à l’ail et au romarin, avec du pain au levain.","emoji":"🌿","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":30,"cookTime":25,"difficulty":"intermediaire","servings":2,"ingredients":[{"id":"agneau-cotelette","qty":5,"unit":"piece"},{"id":"feves","qty":250,"unit":"g","note":"écossées et dérobées"},{"id":"petits-pois","qty":200,"unit":"g"},{"id":"artichaut","qty":2,"unit":"piece","note":"poivrade (petits), parés en quartiers"},{"id":"laitue","qty":150,"unit":"g","note":"romaine en lanières"},{"id":"pancetta","qty":30,"unit":"g","note":"guanciale en lardons"},{"id":"oignon-nouveau","qty":3,"unit":"piece"},{"id":"vin-blanc","qty":80,"unit":"ml"},{"id":"huile-olive","qty":30,"unit":"ml"},{"id":"menthe","qty":15,"unit":"g"},{"id":"romarin","qty":1,"unit":"brin"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"citron","qty":1,"unit":"piece"},{"id":"pain-levain","qty":1,"unit":"piece","note":"grande tranche"},{"id":"pecorino","qty":15,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Parez les artichauts (retirez les feuilles dures, coupez en quartiers, ôtez le foin) et plongez-les dans de l’eau citronnée.","Dans une sauteuse, faites fondre la pancetta 3 min à feu moyen avec 15 ml d’huile, ajoutez les oignons nouveaux émincés 2 min, puis les artichauts égouttés. Déglacez au vin blanc et cuisez 10 min à couvert à feu doux.","Ajoutez les fèves et les petits pois avec 80 ml d’eau, cuisez 5 min à couvert. Incorporez la laitue et la menthe ciselée 1 min, juste pour qu’elle tombe. Salez, poivrez.","Frottez les côtelettes avec l’ail écrasé, le romarin haché, 15 ml d’huile et du sel. Grillez-les dans une poêle-gril fumante 2 à 3 min par face : le gras doit être doré et la chair rosée.","Toastez le pain. Servez la vignarola parsemée de pecorino, les côtelettes par-dessus et le pain à côté."],"tags":["riche en protéines","week-end","sportif"],"seasons":["printemps"],"technique":"grill","flavors":["herbace","frais","grille"]},{"id":"dl-gigot-briam-feta","name":"Tranches de gigot sur briam, légumes du soleil rôtis à la feta","description":"Le briam grec, plat de courgettes, aubergines, poivrons, tomates et pommes de terre confits à l’huile d’olive et à l’origan, gratiné de feta, avec des tranches de gigot grillées.","emoji":"🍆","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":25,"cookTime":70,"difficulty":"facile","servings":4,"ingredients":[{"id":"agneau-gigot","qty":700,"unit":"g","note":"en tranches de 2 cm"},{"id":"courgette","qty":2,"unit":"piece"},{"id":"aubergine","qty":1,"unit":"piece"},{"id":"poivron-rouge","qty":2,"unit":"piece"},{"id":"tomate","qty":4,"unit":"piece"},{"id":"pomme-de-terre","qty":600,"unit":"g"},{"id":"oignon-rouge","qty":2,"unit":"piece"},{"id":"ail","qty":4,"unit":"gousse"},{"id":"huile-olive","qty":60,"unit":"ml"},{"id":"origan","qty":2,"unit":"cac"},{"id":"feta","qty":150,"unit":"g"},{"id":"persil","qty":20,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 190 °C. Coupez pommes de terre, courgettes, aubergine et poivrons en morceaux de 3 cm, les oignons en quartiers et les tomates en dés.","Dans un grand plat, mélangez tous les légumes avec l’ail émincé, 50 ml d’huile, l’origan, du sel et 100 ml d’eau. Couvrez d’aluminium.","Enfournez 40 min à couvert, puis retirez l’aluminium, remuez et poursuivez 25 min : les légumes doivent être confits et légèrement caramélisés, la pomme de terre fondante.","Émiettez la feta sur le briam et remettez 5 min au four, en position gril.","Pendant ce temps, frottez les tranches de gigot avec le reste d’huile, du sel et de l’origan, et grillez-les 3 min par face dans une poêle-gril bien chaude. Laissez reposer 3 min.","Servez le gigot sur le briam, arrosé de jus de citron et parsemé de persil."],"tags":["four","familial","batch cooking","riche en protéines"],"seasons":["ete"],"technique":"four","flavors":["herbace","grille","reconfortant"]},{"id":"dl-kofta-agneau-aubergine-tahini-persil","name":"Kofta d’agneau, aubergine rôtie au tahini, salade de persil et boulgour","description":"Brochettes d’agneau haché aux épices grillées, demi-aubergines fondantes nappées de tahini-yaourt, salade de persil, tomate et oignon au sumac et boulgour.","emoji":"🍢","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"levantine","prepTime":25,"cookTime":35,"difficulty":"facile","servings":2,"ingredients":[{"id":"agneau-hache","qty":260,"unit":"g"},{"id":"aubergine","qty":1,"unit":"piece"},{"id":"tahini","qty":20,"unit":"g"},{"id":"yaourt-grec","qty":100,"unit":"g"},{"id":"boulgour","qty":90,"unit":"g"},{"id":"persil","qty":50,"unit":"g"},{"id":"tomate","qty":2,"unit":"piece"},{"id":"oignon-rouge","qty":1,"unit":"piece"},{"id":"sumac","qty":1,"unit":"cac"},{"id":"ras-el-hanout","qty":2,"unit":"cac","note":"ou baharat"},{"id":"citron","qty":1,"unit":"piece"},{"id":"ail","qty":1,"unit":"gousse"},{"id":"huile-olive","qty":20,"unit":"ml"},{"id":"pignons","qty":15,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : faites tremper la céréale 12 h (une nuit) dans de l’eau tiède additionnée d’1 c. à soupe de jus de citron ou de vinaigre de cidre. Rincez avant de cuire.","Préchauffez le four à 210 °C. Coupez l’aubergine en deux, quadrillez la chair, badigeonnez de 15 ml d’huile et salez. Rôtissez 30 min face coupée vers le bas : la chair doit être fondante.","Couvrez le boulgour de 1,5 fois son volume d’eau bouillante salée, couvrez et laissez gonfler 15 min.","Mélangez l’agneau avec la moitié de l’oignon râpé, les épices, 10 g de persil haché et du sel. Formez 6 boudins autour de brochettes.","Grillez les kofta dans une poêle-gril avec un filet d’huile à feu vif, 8 min en les tournant : elles doivent être bien colorées et juste cuites.","Fouettez tahini, yaourt, ail râpé, jus d’un demi-citron et 2 cuillères d’eau. Hachez grossièrement le reste du persil, mélangez avec tomates en dés, l’autre moitié d’oignon émincée, sumac, reste d’huile et de citron.","Servez l’aubergine nappée de sauce et de pignons grillés, les kofta, le boulgour et la salade de persil."],"tags":["barbecue","riche en protéines","familial","préparation à l’avance"],"seasons":["ete","automne"],"technique":"grill","flavors":["epice","herbace","cremeux"],"restTime":720},{"id":"dl-agneau-haricots-coco-courgettes-romarin","name":"Épaule d’agneau mijotée aux cocos, tomates, courgettes et romarin","description":"Une cocotte provençale de fin d’été : agneau fondant, haricots cocos, tomates, courgettes et blettes parfumés au romarin et à l’ail, finie d’un filet d’huile d’olive.","emoji":"🫘","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":110,"difficulty":"facile","servings":4,"ingredients":[{"id":"agneau-epaule","qty":800,"unit":"g","note":"en morceaux"},{"id":"haricots-blancs","qty":245,"unit":"g","note":"cocos cuits"},{"id":"tomate","qty":4,"unit":"piece"},{"id":"courgette","qty":2,"unit":"piece"},{"id":"epinard","qty":38.5,"unit":"g","note":"blettes, côtes et vert émincés"},{"id":"oignon","qty":2,"unit":"piece"},{"id":"ail","qty":5,"unit":"gousse"},{"id":"carotte","qty":2,"unit":"piece"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"bouillon-volaille","qty":300,"unit":"ml"},{"id":"huile-olive","qty":40,"unit":"ml"},{"id":"romarin","qty":2,"unit":"brin"},{"id":"thym","qty":3,"unit":"brin"},{"id":"pain-levain","qty":4,"unit":"piece","note":"tranches grillées"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"},{"id":"parmesan","qty":60,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["Salez l’agneau. Dans une cocotte, faites-le dorer dans 20 ml d’huile à feu vif en 2 fournées, 5 min chacune. Réservez.","Blanchissez les épinards 2 min dans l’eau bouillante salée, égouttez-les et jetez l’eau de cuisson (cela élimine une bonne partie des oxalates solubles).","À feu moyen, faites suer oignons et carottes en dés 6 min, ajoutez l’ail écrasé, le romarin et le thym. Déglacez au vin blanc et laissez réduire 2 min.","Remettez l’agneau, ajoutez les tomates concassées et le bouillon. Couvrez et laissez mijoter 1 h 15 à feu doux.","Ajoutez les haricots, les courgettes en gros dés et les côtes de blettes, poursuivez 25 min à couvert. Ajoutez le vert des blettes les 5 dernières minutes : l’agneau doit être fondant et le jus légèrement épaissi par les haricots.","Rectifiez l’assaisonnement, arrosez du reste d’huile d’olive crue et servez avec le pain grillé frotté d’ail.","Servez parsemé de parmesan râpé (son calcium limite l’absorption des oxalates)."],"tags":["mijoté","batch cooking","familial","réconfortant"],"seasons":["ete","automne"],"technique":"mijote","flavors":["herbace","reconfortant","umami"],"tips":"Les légumineuses tiennent lieu de féculent ; le pain grillé complète."},{"id":"dl-cotes-porc-fenouil-poires-patate-douce","name":"Côtes de porc, fenouil et poires rôtis, purée de patate douce au gingembre","description":"Côtes de porc saisies puis rôties sur un lit de fenouil et de poires à la sauge, purée de patate douce au beurre et au gingembre, poignée de noisettes concassées.","emoji":"🍐","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":35,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"porc-cote","qty":2,"unit":"piece"},{"id":"fenouil","qty":1,"unit":"piece"},{"id":"poire","qty":1,"unit":"piece"},{"id":"patate-douce","qty":1,"unit":"piece"},{"id":"gingembre","qty":10,"unit":"g"},{"id":"beurre","qty":25,"unit":"g"},{"id":"huile-olive","qty":20,"unit":"ml"},{"id":"sauge","qty":6,"unit":"feuille"},{"id":"noisette","qty":25,"unit":"g"},{"id":"cidre","qty":100,"unit":"ml"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"chou-bruxelles","qty":200,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 200 °C. Coupez le fenouil en quartiers fins, la poire en 8 et les choux de Bruxelles en deux. Mélangez avec l’huile, la sauge et du sel dans un plat, enfournez 15 min.","Épluchez la patate douce, coupez-la en cubes et cuisez-la 15 min à la vapeur. Écrasez-la avec 15 g de beurre et le gingembre râpé, salez.","Salez les côtes de porc et saisissez-les 2 min par face dans une poêle très chaude avec le reste de beurre. Posez-les sur les légumes et enfournez 10 min : le cœur doit être juste rosé (63 °C).","Déglacez la poêle avec le cidre et la moutarde, laissez réduire 2 min pour obtenir un jus sirupeux.","Torréfiez les noisettes concassées 3 min à sec. Servez les côtes nappées de jus avec les légumes rôtis, la purée et les noisettes."],"tags":["four","riche en protéines","réconfortant"],"seasons":["automne","hiver"],"technique":"roti","flavors":["fruite","grille","reconfortant"]},{"id":"dl-porc-pois-chiches-epinards-pimenton","name":"Échine de porc aux pois chiches, épinards et pimentón à la sévillane","description":"Inspiré des espinacas con garbanzos : pois chiches et épinards liés au pain frit, à l’ail, au cumin et au pimentón, avec des tranches d’échine de porc grillées au paprika fumé.","emoji":"🌶️","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"espagnole","prepTime":15,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"porc-echine","qty":320,"unit":"g","note":"en tranches de 1,5 cm"},{"id":"pois-chiches","qty":300,"unit":"g","note":"égouttés"},{"id":"epinard","qty":27.5,"unit":"g"},{"id":"pain-levain","qty":1,"unit":"piece","note":"tranche"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"paprika","qty":2,"unit":"cac","note":"pimentón fumé"},{"id":"cumin","qty":1,"unit":"cac"},{"id":"vinaigre-cidre","qty":15,"unit":"ml","note":"de Xérès"},{"id":"huile-olive","qty":40,"unit":"ml"},{"id":"tomate","qty":1,"unit":"piece"},{"id":"poivron-grille","qty":100,"unit":"g","note":"piquillos"},{"id":"citron","qty":1,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"},{"id":"parmesan","qty":30,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["Frottez l’échine avec 1 cuillère de pimentón, du sel et 10 ml d’huile. Réservez.","Blanchissez les épinards 2 min dans l’eau bouillante salée, égouttez-les et jetez l’eau de cuisson (cela élimine une bonne partie des oxalates solubles).","Dans une sauteuse, faites frire la tranche de pain et l’ail entier dans 20 ml d’huile 3 min à feu moyen jusqu’à ce qu’ils soient dorés. Mixez-les au pilon avec le cumin, le reste de pimentón et le vinaigre pour obtenir une pâte.","Dans la même sauteuse, faites fondre la tomate râpée 3 min, ajoutez les épinards par poignées jusqu’à ce qu’ils tombent (3 min).","Ajoutez les pois chiches, la pâte de pain et 150 ml d’eau. Laissez mijoter 10 min à feu doux : la sauce doit devenir épaisse et nappante. Ajoutez les piquillos en lanières.","Grillez l’échine dans une poêle-gril très chaude 4 min par face, puis laissez reposer 3 min.","Servez les tranches de porc sur les pois chiches, avec un quartier de citron.","Servez parsemé de parmesan râpé (son calcium limite l’absorption des oxalates)."],"tags":["une poêle","économique","riche en protéines"],"seasons":["automne","hiver","printemps"],"technique":"poele","flavors":["fume","epice","umami"],"tips":"Les pois chiches tiennent lieu de féculent."},{"id":"dl-gratin-brocoli-chou-fleur-jambon-comte","name":"Gratin de brocoli, chou-fleur et jambon au comté, pommes de terre","description":"Un gratin familial riche en calcium : brocoli, chou-fleur et pommes de terre enrobés d’une béchamel au lait entier et au comté, avec des dés de jambon et une croûte dorée.","emoji":"🧀","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":40,"difficulty":"facile","servings":4,"ingredients":[{"id":"brocoli","qty":1,"unit":"piece"},{"id":"chou-fleur","qty":1,"unit":"piece"},{"id":"pomme-de-terre","qty":600,"unit":"g"},{"id":"jambon-blanc","qty":300,"unit":"g","note":"en dés"},{"id":"comte","qty":180,"unit":"g","note":"râpé"},{"id":"lait","qty":700,"unit":"ml"},{"id":"beurre","qty":40,"unit":"g"},{"id":"farine","qty":40,"unit":"g"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"oeuf","qty":2,"unit":"piece"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"graines-courge","qty":30,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 200 °C. Coupez brocoli et chou-fleur en fleurettes, les pommes de terre en rondelles de 5 mm. Cuisez les pommes de terre 8 min et les fleurettes 5 min à l’eau bouillante salée : ils doivent rester fermes. Égouttez bien.","Béchamel : faites fondre le beurre, ajoutez la farine et remuez 2 min à feu moyen. Versez le lait froid en fouettant et cuisez 6 min jusqu’à épaississement. Hors du feu, ajoutez la moutarde, la muscade, 120 g de comté, puis les œufs battus.","Dans un grand plat beurré, alternez pommes de terre, légumes et jambon. Nappez de béchamel.","Parsemez du reste de comté et des graines de courge. Enfournez 25 min : le dessus doit être bien doré et la sauce bouillonner sur les bords.","Laissez reposer 5 min avant de servir."],"tags":["four","familial","réconfortant","batch cooking"],"seasons":["automne","hiver"],"technique":"four","flavors":["lacte","cremeux","reconfortant"]},{"id":"dl-echine-potimarron-chou-frise-cidre","name":"Échine de porc rôtie, potimarron, chou frisé et pommes de terre, jus au cidre","description":"Rôti d’échine posé sur potimarron et pommes de terre qui confisent dans son jus, chou frisé croquant ajouté en fin de cuisson et sauce au cidre et à la moutarde à l’ancienne.","emoji":"🎃","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":90,"difficulty":"facile","servings":4,"ingredients":[{"id":"porc-echine","qty":900,"unit":"g","note":"en rôti ficelé"},{"id":"potimarron","qty":1,"unit":"piece","note":"en quartiers avec la peau"},{"id":"pomme-de-terre","qty":500,"unit":"g"},{"id":"chou-vert","qty":400,"unit":"g","note":"chou frisé (kale) effeuillé"},{"id":"oignon","qty":2,"unit":"piece"},{"id":"cidre","qty":300,"unit":"ml"},{"id":"moutarde","qty":2,"unit":"cas","note":"à l’ancienne"},{"id":"creme-fraiche","qty":60,"unit":"ml"},{"id":"graisse-canard","qty":20,"unit":"g","note":"ou saindoux"},{"id":"thym","qty":4,"unit":"brin"},{"id":"ail","qty":4,"unit":"gousse"},{"id":"graines-courge","qty":30,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 180 °C. Salez le rôti, frottez-le de moutarde et faites-le dorer de tous côtés dans la graisse, 8 min à feu vif, dans un grand plat allant sur le feu.","Disposez autour le potimarron, les pommes de terre en quartiers, les oignons en quartiers, l’ail en chemise et le thym. Versez 200 ml de cidre.","Enfournez 1 h 10 en arrosant toutes les 20 min : à cœur, la viande doit atteindre 68 °C et les légumes être fondants.","Ajoutez le chou frisé huilé sur les légumes et remettez 10 min : il doit être tombé avec des bords croustillants.","Sortez le rôti, couvrez-le et laissez reposer 10 min. Déglacez le plat avec le reste de cidre sur le feu, ajoutez la crème et le reste de moutarde, laissez réduire 3 min.","Tranchez le rôti, servez avec les légumes, la sauce et les graines de courge torréfiées."],"tags":["four","week-end","familial","réconfortant"],"seasons":["automne","hiver"],"technique":"roti","flavors":["reconfortant","fruite","grille"]},{"id":"dl-filet-mignon-chou-pointu-carvi-celeri","name":"Filet mignon, chou pointu sauté au carvi, carottes et purée de céleri-pommes","description":"À l’allemande : filet mignon rôti, chou pointu et carottes sautés au beurre et au carvi, purée de céleri-rave et pommes de terre au raifort, jus à la bière.","emoji":"🥬","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"europe-centrale","prepTime":20,"cookTime":35,"difficulty":"facile","servings":2,"ingredients":[{"id":"porc-filet-mignon","qty":400,"unit":"g"},{"id":"chou-vert","qty":400,"unit":"g","note":"chou pointu émincé"},{"id":"carotte","qty":2,"unit":"piece"},{"id":"celeri-rave","qty":350,"unit":"g"},{"id":"pomme-de-terre","qty":250,"unit":"g"},{"id":"raifort","qty":1,"unit":"cas"},{"id":"beurre","qty":30,"unit":"g"},{"id":"graines-fenouil","qty":1,"unit":"cac","note":"carvi"},{"id":"biere","qty":150,"unit":"ml"},{"id":"lait","qty":80,"unit":"ml"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"vinaigre-cidre","qty":10,"unit":"ml"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez le céleri et les pommes de terre en cubes 20 min à l’eau salée. Égouttez et écrasez avec le lait chaud, 10 g de beurre et le raifort.","Préchauffez le four à 190 °C. Salez le filet mignon, dorez-le 5 min sur toutes ses faces dans 10 g de beurre, puis enfournez 15 min (cœur à 63 °C). Laissez reposer 5 min.","Déglacez la poêle avec la bière, laissez réduire de moitié 4 min à feu vif.","Dans une sauteuse, faites fondre l’oignon émincé et le carvi dans le reste de beurre 3 min, ajoutez les carottes en julienne et le chou, faites sauter 7 min à feu vif : le chou doit rester croquant et un peu doré. Arrosez de vinaigre, salez.","Tranchez le filet, servez avec le chou, la purée et le jus à la bière, parsemé de persil."],"tags":["riche en protéines","sportif","réconfortant"],"seasons":["automne","hiver","printemps"],"technique":"poele","flavors":["umami","acidule","reconfortant"]},{"id":"dl-poulet-zaatar-chou-fleur-tahini-freekeh","name":"Hauts de cuisse au zaatar, chou-fleur rôti, pois chiches et sauce tahini","description":"Poulet mariné au yaourt et zaatar rôti sur une plaque de chou-fleur entier en fleurettes et pois chiches, nappé de tahini citronné et de persil, avec du freekeh.","emoji":"🍗","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"levantine","prepTime":15,"cookTime":35,"restTime":720,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"poulet-haut-cuisse-desosse","qty":3,"unit":"piece"},{"id":"chou-fleur","qty":500,"unit":"g"},{"id":"pois-chiches","qty":150,"unit":"g"},{"id":"yaourt-grec","qty":60,"unit":"g"},{"id":"zaatar","qty":2,"unit":"cas"},{"id":"tahini","qty":25,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"huile-olive","qty":30,"unit":"ml"},{"id":"boulgour","qty":70,"unit":"g","note":"freekeh"},{"id":"persil","qty":30,"unit":"g"},{"id":"oignon-rouge","qty":1,"unit":"piece"},{"id":"grenade","qty":0.5,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : faites tremper la céréale 12 h (une nuit) dans de l’eau tiède additionnée d’1 c. à soupe de jus de citron ou de vinaigre de cidre. Rincez avant de cuire.","Mélangez le poulet avec le yaourt, 1 cuillère de zaatar, une gousse d’ail râpée et du sel. Laissez mariner 30 min (ou toute une nuit au frais).","Préchauffez le four à 220 °C. Sur une plaque, mélangez le chou-fleur en fleurettes, l’oignon rouge en quartiers, les pois chiches séchés, l’huile et le reste de zaatar. Posez le poulet par-dessus.","Enfournez 30 à 35 min : le poulet doit être doré et caramélisé sur les bords, le chou-fleur bien grillé.","Cuisez le freekeh 15 min dans 2,5 fois son volume d’eau salée, couvert.","Fouettez le tahini avec le jus d’un demi-citron, l’autre gousse d’ail râpée et 3 cuillères d’eau froide jusqu’à une sauce lisse et pâle.","Servez sur le freekeh, nappé de tahini, parsemé de persil, de grenade et arrosé du reste de citron."],"tags":["four","préparation à l’avance","riche en protéines","lunch box"],"seasons":["automne","hiver","printemps"],"technique":"roti","flavors":["herbace","acidule","epice"]},{"id":"dl-fricassee-poulet-poireaux-champignons-riz-complet","name":"Fricassée de poulet aux poireaux, champignons et carottes, riz complet","description":"Une fricassée bourgeoise allégée en crème et chargée de légumes : cuisses de poulet, poireaux fondus, champignons et carottes au vin blanc et à l’estragon, sur un riz complet.","emoji":"🍄","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":50,"difficulty":"facile","servings":4,"ingredients":[{"id":"poulet-cuisse","qty":4,"unit":"piece"},{"id":"poireau","qty":3,"unit":"piece"},{"id":"champignon","qty":400,"unit":"g"},{"id":"carotte","qty":3,"unit":"piece"},{"id":"riz-complet","qty":280,"unit":"g"},{"id":"vin-blanc","qty":200,"unit":"ml"},{"id":"bouillon-volaille","qty":300,"unit":"ml"},{"id":"creme-fraiche","qty":100,"unit":"ml"},{"id":"beurre","qty":25,"unit":"g"},{"id":"estragon","qty":10,"unit":"g"},{"id":"echalote","qty":2,"unit":"piece"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"citron","qty":0.5,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : faites tremper le riz complet 12 à 24 h dans de l’eau tiède, jetez l’eau et rincez avant de cuire.","Salez les cuisses et dorez-les côté peau dans 15 g de beurre 8 min à feu moyen-vif dans une cocotte, puis 3 min côté chair. Réservez et retirez l’excès de gras.","Faites suer les échalotes, les poireaux en rondelles et les carottes en biseau 8 min à feu moyen. Déglacez au vin blanc, laissez réduire 3 min.","Remettez le poulet, versez le bouillon, couvrez et laissez mijoter 30 min à feu doux.","Pendant ce temps, cuisez le riz complet 30 à 35 min dans 2,5 fois son volume d’eau salée. Faites sauter les champignons émincés dans le reste de beurre 6 min à feu vif jusqu’à ce qu’ils soient dorés.","Ajoutez les champignons, la crème et la moutarde dans la cocotte et laissez réduire 5 min à découvert pour que la sauce nappe la cuillère. Ajoutez l’estragon et un trait de citron.","Servez la fricassée sur le riz complet."],"tags":["mijoté","familial","réconfortant","batch cooking","préparation à l’avance"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["cremeux","herbace","reconfortant"],"restTime":720},{"id":"dl-salade-poulet-sarrasin-asperges-feta","name":"Salade tiède de poulet, sarrasin grillé, asperges, petits pois et feta à la menthe","description":"Kasha de sarrasin croquante, asperges vertes, petits pois et radis, blanc de poulet grillé au citron, feta et menthe, vinaigrette à l’huile d’olive.","emoji":"🥗","category":"salade-composee","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":20,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"poulet-blanc","qty":2,"unit":"piece"},{"id":"sarrasin","qty":120,"unit":"g","note":"kasha grillée"},{"id":"asperge","qty":10,"unit":"piece","note":"vertes"},{"id":"petits-pois","qty":200,"unit":"g"},{"id":"radis","qty":8,"unit":"piece"},{"id":"roquette","qty":60,"unit":"g"},{"id":"feta","qty":80,"unit":"g"},{"id":"menthe","qty":15,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"huile-olive","qty":40,"unit":"ml"},{"id":"graines-courge","qty":20,"unit":"g"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : faites tremper la céréale 12 h (une nuit) dans de l’eau tiède additionnée d’1 c. à soupe de jus de citron ou de vinaigre de cidre. Rincez avant de cuire.","Cuisez le sarrasin 10 min dans 2 fois son volume d’eau salée frémissante : il doit être tendre mais encore un peu croquant. Égouttez et étalez pour qu’il tiédisse.","Coupez les asperges en tronçons de 4 cm et cuisez-les 3 min à l’eau bouillante salée avec les petits pois, puis rafraîchissez.","Aplatissez légèrement les blancs, frottez-les de 10 ml d’huile, du zeste de citron et du sel. Grillez 5 min par face dans une poêle-gril à feu moyen-vif : le cœur doit être juste blanc. Laissez reposer 3 min et tranchez.","Fouettez le jus du citron, la moutarde et 30 ml d’huile. Mélangez avec le sarrasin, les légumes, les radis en rondelles et la menthe ciselée.","Dressez sur la roquette, ajoutez le poulet, la feta émiettée et les graines de courge torréfiées."],"tags":["lunch box","repas froid","riche en protéines","sans gluten","préparation à l’avance"],"seasons":["printemps"],"technique":"grill","flavors":["frais","herbace","acidule"],"restTime":720},{"id":"dl-dinde-haricots-verts-tomates-amandes","name":"Escalopes de dinde, haricots verts, tomates et amandes, pommes de terre à l’ail","description":"Escalopes de dinde dorées au beurre, poêlée de haricots verts aux tomates cerises et amandes effilées grillées, pommes de terre sautées à l’ail et au persil.","emoji":"🫛","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":30,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"dinde-escalope","qty":3,"unit":"piece"},{"id":"haricots-verts","qty":350,"unit":"g"},{"id":"tomate-cerise","qty":15,"unit":"piece"},{"id":"amande","qty":25,"unit":"g","note":"effilées"},{"id":"pomme-de-terre","qty":400,"unit":"g"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"beurre","qty":25,"unit":"g"},{"id":"huile-olive","qty":20,"unit":"ml"},{"id":"persil","qty":15,"unit":"g"},{"id":"citron","qty":0.5,"unit":"piece"},{"id":"origan","qty":1,"unit":"cac"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Coupez les pommes de terre en cubes de 2 cm et faites-les dorer dans l’huile d’olive 20 min à feu moyen en remuant, à couvert les 10 premières minutes. Ajoutez 2 gousses d’ail hachées et le persil les 2 dernières minutes.","Cuisez les haricots verts 6 min à l’eau bouillante salée et rafraîchissez-les.","Faites griller les amandes à sec 2 min à feu moyen jusqu’à ce qu’elles blondissent. Réservez.","Salez les escalopes et dorez-les dans 15 g de beurre 3 min par face à feu moyen-vif. Réservez au chaud.","Dans la même poêle, faites sauter les tomates cerises coupées en deux avec le reste de beurre, l’ail restant et l’origan 2 min, ajoutez les haricots 2 min. Arrosez de citron.","Servez la dinde avec les haricots parsemés d’amandes et les pommes de terre."],"tags":["rapide","économique","riche en protéines","familial"],"seasons":["ete"],"technique":"poele","flavors":["grille","herbace"]},{"id":"dl-boulettes-dinde-fenouil-cannellini-blettes","name":"Boulettes de dinde au fenouil, cannellini et blettes à la tomate","description":"Polpette de dinde parfumées aux graines de fenouil et au parmesan, mijotées dans une sauce tomate aux haricots blancs et aux blettes, à saucer avec du pain au levain.","emoji":"🍅","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":25,"cookTime":30,"difficulty":"facile","servings":4,"ingredients":[{"id":"dinde-hachee","qty":600,"unit":"g"},{"id":"parmesan","qty":50,"unit":"g"},{"id":"oeuf","qty":1,"unit":"piece"},{"id":"panure","qty":40,"unit":"g"},{"id":"graines-fenouil","qty":2,"unit":"cac"},{"id":"haricots-blancs","qty":350,"unit":"g","note":"cannellini"},{"id":"epinard","qty":38.5,"unit":"g","note":"blettes"},{"id":"tomates-concassees","qty":800,"unit":"g"},{"id":"fenouil","qty":1,"unit":"piece","note":"émincé"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"huile-olive","qty":40,"unit":"ml"},{"id":"piment-espelette","qty":1,"unit":"pincee"},{"id":"basilic","qty":15,"unit":"g"},{"id":"pain-levain","qty":4,"unit":"piece","note":"tranches"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Mélangez la dinde, l’œuf, la chapelure, 30 g de parmesan, 1 cuillère de graines de fenouil écrasées, une gousse d’ail râpée et du sel. Formez 16 boulettes.","Blanchissez les épinards 2 min dans l’eau bouillante salée, égouttez-les et jetez l’eau de cuisson (cela élimine une bonne partie des oxalates solubles).","Dorez les boulettes dans 20 ml d’huile à feu moyen-vif 6 min en les roulant. Réservez.","Dans la même sauteuse, faites suer l’oignon, le fenouil émincé et le reste d’ail 7 min. Ajoutez le reste de graines de fenouil, le piment et les tomates. Laissez frémir 10 min.","Ajoutez les haricots égouttés, les côtes de blettes émincées et les boulettes. Couvrez et laissez mijoter 12 min à feu doux.","Ajoutez le vert des blettes haché et cuisez 3 min à découvert. Servez parsemé du reste de parmesan, de basilic et d’un filet d’huile, avec le pain grillé."],"tags":["familial","batch cooking","économique","réconfortant"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["umami","herbace","reconfortant"]},{"id":"dl-magret-celeri-rave-kale-noisettes","name":"Magret, purée de céleri-rave, chou kale au beurre noisette et airelles","description":"Magret rosé à la peau croustillante, purée soyeuse de céleri-rave et pommes de terre, chou kale sauté au beurre noisette et noisettes, quelques airelles pour l’acidité.","emoji":"🦆","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"canard-magret","qty":1,"unit":"piece"},{"id":"celeri-rave","qty":400,"unit":"g"},{"id":"pomme-de-terre","qty":250,"unit":"g"},{"id":"chou-vert","qty":250,"unit":"g","note":"kale effeuillé"},{"id":"noisette","qty":25,"unit":"g"},{"id":"airelles","qty":40,"unit":"g"},{"id":"beurre","qty":20,"unit":"g"},{"id":"lait","qty":100,"unit":"ml"},{"id":"echalote","qty":1,"unit":"piece"},{"id":"thym","qty":2,"unit":"brin"},{"id":"vinaigre-balsamique","qty":15,"unit":"ml"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez le céleri-rave et les pommes de terre en cubes 20 min à l’eau salée. Égouttez et mixez avec le lait chaud et 10 g de beurre jusqu’à une purée lisse.","Quadrillez la peau du magret sans entailler la chair, salez. Posez-le côté peau dans une poêle froide, chauffez à feu moyen et cuisez 8 min en retirant le gras fondu, puis 4 min côté chair. Laissez reposer 6 min sous aluminium.","Dans 1 cuillère de graisse du magret, faites revenir l’échalote 1 min, déglacez au balsamique et ajoutez les airelles et le thym 2 min.","Faites mousser le reste de beurre jusqu’à ce qu’il sente la noisette, ajoutez les noisettes concassées et le kale, faites sauter 4 min à feu vif : le chou doit être tombé mais vert vif.","Tranchez le magret, servez sur la purée avec le kale et la sauce aux airelles."],"tags":["week-end","riche en protéines","réconfortant"],"seasons":["automne","hiver"],"technique":"poele","flavors":["fruite","umami","grille"]},{"id":"dl-cuisses-canard-lentilles-carottes-epinards","name":"Cuisses de canard braisées aux lentilles, carottes et épinards","description":"Cuisses de canard dorées puis braisées sur des lentilles vertes du Puy, carottes et céleri, finies avec une poignée d’épinards et un filet de vinaigre de Xérès.","emoji":"🍲","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":75,"difficulty":"facile","servings":4,"ingredients":[{"id":"canard-cuisse","qty":4,"unit":"piece"},{"id":"lentilles-vertes","qty":240,"unit":"g"},{"id":"carotte","qty":4,"unit":"piece"},{"id":"celeri-branche","qty":2,"unit":"piece"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"epinard","qty":55,"unit":"g"},{"id":"bouillon-volaille","qty":800,"unit":"ml"},{"id":"vin-rouge","qty":100,"unit":"ml"},{"id":"vinaigre-cidre","qty":15,"unit":"ml","note":"de Xérès"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"girofle","qty":1,"unit":"pincee"},{"id":"persil","qty":15,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"},{"id":"parmesan","qty":60,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["La veille : faites tremper les lentilles 12 h (une nuit) dans de l’eau tiède, jetez l’eau et rincez avant de cuire.","Salez les cuisses et dorez-les côté peau dans une cocotte à feu moyen 10 min pour faire fondre le gras, puis 3 min côté chair. Réservez et gardez 2 cuillères de graisse.","Blanchissez les épinards 2 min dans l’eau bouillante salée, égouttez-les et jetez l’eau de cuisson (cela élimine une bonne partie des oxalates solubles).","Faites suer l’oignon, les carottes en rondelles épaisses et le céleri dans la graisse 6 min. Ajoutez l’ail, le thym, le laurier et le girofle. Déglacez au vin rouge et réduisez 2 min.","Ajoutez les lentilles rincées et le bouillon, posez les cuisses dessus, peau hors du liquide. Couvrez et laissez mijoter 45 min à feu doux.","Découvrez et passez 15 min sous le gril du four à 220 °C : la peau doit être croustillante et les lentilles avoir absorbé presque tout le bouillon.","Retirez les cuisses, incorporez les épinards aux lentilles chaudes jusqu’à ce qu’ils tombent (2 min), ajoutez le vinaigre et le persil. Servez les cuisses sur les lentilles.","Servez parsemé de parmesan râpé (son calcium limite l’absorption des oxalates)."],"tags":["mijoté","réconfortant","familial","sans gluten","préparation à l’avance"],"seasons":["automne","hiver"],"technique":"braise","flavors":["umami","reconfortant","acidule"],"tips":"Les lentilles tiennent lieu de féculent.","restTime":720},{"id":"dl-pintade-topinambours-poireaux-noisettes","name":"Pintade en cocotte, topinambours, poireaux et pommes de terre aux noisettes","description":"Pintade dorée puis cuite à l’étouffée au vin blanc sur un lit de topinambours, poireaux et pommes de terre, parsemée de noisettes grillées et d’estragon.","emoji":"🐓","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":75,"difficulty":"facile","servings":4,"ingredients":[{"id":"pintade","qty":1,"unit":"piece"},{"id":"topinambour","qty":500,"unit":"g"},{"id":"poireau","qty":3,"unit":"piece"},{"id":"pomme-de-terre","qty":500,"unit":"g"},{"id":"vin-blanc","qty":200,"unit":"ml"},{"id":"bouillon-volaille","qty":200,"unit":"ml"},{"id":"beurre","qty":30,"unit":"g"},{"id":"noisette","qty":40,"unit":"g"},{"id":"ail","qty":4,"unit":"gousse"},{"id":"thym","qty":4,"unit":"brin"},{"id":"estragon","qty":10,"unit":"g"},{"id":"creme-fraiche","qty":60,"unit":"ml"},{"id":"citron","qty":0.5,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Coupez la pintade en 6 morceaux (ou demandez au volailler), salez. Dorez-les dans le beurre à feu moyen-vif dans une grande cocotte, 4 min par face. Réservez.","Faites revenir les poireaux en tronçons de 3 cm 5 min dans la graisse. Ajoutez les topinambours et les pommes de terre en gros morceaux, l’ail en chemise et le thym. Déglacez au vin blanc.","Posez la pintade sur les légumes, versez le bouillon, couvrez et cuisez 50 min au four à 170 °C.","Découvrez, montez le four à 210 °C et poursuivez 15 min : la peau doit dorer et les topinambours être fondants à cœur.","Torréfiez les noisettes concassées 3 min. Retirez la viande, mélangez la crème, l’estragon et le citron au jus des légumes, puis remettez la pintade.","Servez parsemé de noisettes."],"tags":["four","week-end","familial","réconfortant"],"seasons":["automne","hiver"],"technique":"braise","flavors":["reconfortant","herbace","umami"]},{"id":"dl-frittata-brocoli-petits-pois-ricotta","name":"Frittata au four aux brocolis, petits pois, ricotta et menthe, pain de seigle","description":"Une épaisse frittata généreuse en légumes verts et piquée de cuillerées de ricotta fondante, au parmesan et à la menthe, servie avec du pain de seigle et une salade de roquette.","emoji":"🍳","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":15,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"oeuf","qty":6,"unit":"piece"},{"id":"brocoli","qty":300,"unit":"g"},{"id":"petits-pois","qty":150,"unit":"g"},{"id":"ricotta","qty":125,"unit":"g"},{"id":"parmesan","qty":40,"unit":"g"},{"id":"oignon-nouveau","qty":3,"unit":"piece"},{"id":"menthe","qty":10,"unit":"g"},{"id":"huile-olive","qty":20,"unit":"ml"},{"id":"pain-seigle","qty":3,"unit":"piece"},{"id":"roquette","qty":60,"unit":"g"},{"id":"citron","qty":0.5,"unit":"piece"},{"id":"graines-courge","qty":20,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 190 °C. Coupez le brocoli en petites fleurettes, la tige en dés. Cuisez-les 3 min avec les petits pois à l’eau bouillante salée et égouttez soigneusement.","Dans une poêle de 24 cm allant au four, faites suer les oignons nouveaux dans 15 ml d’huile 2 min. Ajoutez les légumes égouttés.","Battez les œufs avec le parmesan, la menthe ciselée, du sel et du poivre. Versez sur les légumes et déposez la ricotta par cuillerées.","Cuisez 3 min à feu moyen sans remuer pour saisir le dessous, puis enfournez 15 min : la frittata doit être gonflée, dorée et juste prise au centre.","Assaisonnez la roquette avec le reste d’huile et le citron. Servez la frittata en parts avec la salade parsemée de graines de courge et le pain de seigle."],"tags":["rapide","économique","riche en protéines","repas froid"],"seasons":["printemps","hiver"],"technique":"four","flavors":["herbace","lacte","frais"]},{"id":"dl-shakshuka-verte-poireaux-feta","name":"Shakshuka verte aux poireaux, épinards, pois chiches et feta","description":"Une poêlée de poireaux, courgette, épinards et pois chiches au cumin dans laquelle on poche des œufs, avec feta, yaourt, herbes et pain au levain grillé.","emoji":"🥚","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"levantine","prepTime":15,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"oeuf","qty":5,"unit":"piece"},{"id":"poireau","qty":2,"unit":"piece"},{"id":"courgette","qty":1,"unit":"piece"},{"id":"epinard","qty":19.25,"unit":"g"},{"id":"pois-chiches","qty":150,"unit":"g"},{"id":"feta","qty":70,"unit":"g"},{"id":"yaourt-grec","qty":80,"unit":"g"},{"id":"cumin","qty":1,"unit":"cac"},{"id":"piment-espelette","qty":1,"unit":"pincee","note":"ou flocons d’Alep"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"huile-olive","qty":25,"unit":"ml"},{"id":"coriandre","qty":15,"unit":"g"},{"id":"aneth","qty":10,"unit":"g"},{"id":"citron","qty":0.5,"unit":"piece"},{"id":"pain-levain","qty":3,"unit":"piece","note":"tranches"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Dans une grande poêle, faites fondre les poireaux émincés dans l’huile 8 min à feu moyen, sans coloration. Ajoutez la courgette en dés, l’ail et le cumin, poursuivez 4 min.","Blanchissez les épinards 2 min dans l’eau bouillante salée, égouttez-les et jetez l’eau de cuisson (cela élimine une bonne partie des oxalates solubles).","Ajoutez les pois chiches et les épinards par poignées ; laissez-les tomber 3 min. Mouillez de 60 ml d’eau, salez et ajoutez le jus du citron.","Creusez 5 puits, cassez-y les œufs. Couvrez et cuisez 6 à 8 min à feu doux : les blancs doivent être pris, les jaunes encore coulants.","Émiettez la feta, ajoutez des cuillerées de yaourt, les herbes hachées et le piment.","Servez directement dans la poêle avec le pain grillé."],"tags":["rapide","une poêle","économique"],"seasons":["hiver","printemps"],"technique":"poele","flavors":["herbace","epice","frais"]},{"id":"dl-saumon-brocoli-sarrasin-kefir-aneth","name":"Saumon rôti, brocoli, petits pois et kasha, sauce kéfir à l’aneth","description":"Un bol nordique très dense : pavés de saumon rôtis, kasha de sarrasin au beurre, brocoli et petits pois, sauce kéfir-aneth-raifort et graines de courge.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"nordique","prepTime":15,"cookTime":20,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"saumon","qty":2,"unit":"piece"},{"id":"sarrasin","qty":110,"unit":"g"},{"id":"brocoli","qty":300,"unit":"g"},{"id":"petits-pois","qty":150,"unit":"g"},{"id":"kefir","qty":120,"unit":"ml"},{"id":"aneth","qty":15,"unit":"g"},{"id":"raifort","qty":1,"unit":"cac"},{"id":"citron","qty":1,"unit":"piece"},{"id":"beurre","qty":15,"unit":"g"},{"id":"graines-courge","qty":20,"unit":"g"},{"id":"concombre","qty":0.5,"unit":"piece"},{"id":"huile-olive","qty":10,"unit":"ml"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : faites tremper la céréale 12 h (une nuit) dans de l’eau tiède additionnée d’1 c. à soupe de jus de citron ou de vinaigre de cidre. Rincez avant de cuire.","Préchauffez le four à 200 °C. Posez le saumon salé sur une plaque, arrosez d’huile et de zeste de citron, enfournez 10 à 12 min : la chair doit être nacrée au centre.","Cuisez le sarrasin 10 min dans 2 fois son volume d’eau salée, puis ajoutez le beurre.","Cuisez le brocoli en fleurettes 4 min à la vapeur, ajoutez les petits pois la dernière minute.","Mélangez le kéfir avec l’aneth haché, le raifort, le jus d’un demi-citron, le concombre en petits dés et du sel.","Torréfiez les graines de courge 3 min à sec. Dressez kasha, légumes et saumon, nappez de sauce et parsemez de graines."],"tags":["rapide","fermenté","riche en protéines","sans gluten","sportif","préparation à l’avance"],"seasons":[],"technique":"four","flavors":["frais","herbace","lacte"],"restTime":720},{"id":"dl-maquereau-fenouil-orange-pommes-de-terre","name":"Maquereau rôti, salade de fenouil à l’orange, roquette et pommes de terre aux câpres","description":"Filets de maquereau à la peau croustillante, salade crue de fenouil, orange et olives, pommes de terre tièdes aux câpres et au persil — iodé, frais et riche en oméga-3.","emoji":"🍊","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":20,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"maquereau","qty":2,"unit":"piece","note":"en filets"},{"id":"fenouil","qty":1,"unit":"piece"},{"id":"orange","qty":2,"unit":"piece"},{"id":"roquette","qty":60,"unit":"g"},{"id":"olive","qty":30,"unit":"g"},{"id":"pomme-de-terre","qty":400,"unit":"g"},{"id":"capres","qty":1,"unit":"cas"},{"id":"persil","qty":15,"unit":"g"},{"id":"huile-olive","qty":30,"unit":"ml"},{"id":"vinaigre-cidre","qty":10,"unit":"ml"},{"id":"oignon-rouge","qty":0.5,"unit":"piece"},{"id":"graines-fenouil","qty":1,"unit":"cac"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez les pommes de terre coupées en deux 15 min à l’eau salée. Égouttez et mélangez tièdes avec les câpres, le persil, 10 ml d’huile et le vinaigre.","Pelez les oranges à vif et coupez-les en rondelles en récupérant le jus. Émincez le fenouil très finement (mandoline) et l’oignon rouge.","Mélangez fenouil, oignon, oranges, olives, le jus d’orange récupéré et 10 ml d’huile ; salez. Laissez macérer 10 min.","Salez les filets de maquereau, frottez la peau de graines de fenouil écrasées. Cuisez-les côté peau dans le reste d’huile 3 min à feu moyen-vif, en les pressant pour qu’ils restent plats, puis 1 min côté chair.","Dressez la roquette, la salade de fenouil, les pommes de terre et le maquereau, peau croustillante vers le haut."],"tags":["rapide","économique","riche en protéines"],"seasons":["hiver","printemps"],"technique":"poele","flavors":["iode","acidule","frais"]},{"id":"dl-sardines-farcies-blettes-polenta","name":"Sardines farcies aux blettes à la niçoise, tomates rôties et polenta","description":"Sardines ouvertes en portefeuille, farcies de blettes, parmesan, œuf et ail, gratinées au four sur des tomates, avec une polenta moelleuse à l’huile d’olive.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":35,"cookTime":25,"difficulty":"intermediaire","servings":2,"ingredients":[{"id":"sardine","qty":10,"unit":"piece","note":"vidées et ouvertes"},{"id":"epinard","qty":27.5,"unit":"g","note":"blettes"},{"id":"oeuf","qty":1,"unit":"piece"},{"id":"parmesan","qty":40,"unit":"g"},{"id":"panure","qty":20,"unit":"g"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"tomate","qty":3,"unit":"piece"},{"id":"polenta","qty":120,"unit":"g"},{"id":"huile-olive","qty":40,"unit":"ml"},{"id":"persil","qty":15,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"origan","qty":1,"unit":"cac"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 200 °C. Ébouillantez les blettes 3 min, rafraîchissez, pressez fort et hachez-les.","Blanchissez les épinards 2 min dans l’eau bouillante salée, égouttez-les et jetez l’eau de cuisson (cela élimine une bonne partie des oxalates solubles).","Mélangez les blettes avec l’œuf, 30 g de parmesan, l’ail haché, le persil, du sel et du poivre.","Coupez les tomates en rondelles épaisses dans un plat huilé, salez et parsemez d’origan. Déposez une cuillerée de farce sur chaque sardine côté chair, refermez et posez-les sur les tomates.","Mélangez la chapelure et le reste du parmesan, parsemez sur les sardines, arrosez de 20 ml d’huile. Enfournez 20 min : le dessus doit être doré et croustillant.","Pendant ce temps, versez la polenta en pluie dans 500 ml d’eau bouillante salée, cuisez 10 min à feu doux en remuant et ajoutez le reste d’huile.","Servez les sardines sur la polenta avec un quartier de citron."],"tags":["four","économique","riche en protéines"],"seasons":["ete","automne"],"technique":"four","flavors":["iode","herbace","grille"]},{"id":"dl-truite-patate-douce-kale-noix","name":"Truite poêlée, écrasé de patate douce et céleri, chou kale aux noix et citron","description":"Filets de truite saisis côté peau, écrasé de patate douce et céleri-rave au beurre, chou kale poêlé à l’ail, noix grillées et citron, sauce crème-ciboulette.","emoji":"🐠","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"truite","qty":2,"unit":"piece","note":"en filets"},{"id":"patate-douce","qty":1,"unit":"piece"},{"id":"celeri-rave","qty":250,"unit":"g"},{"id":"chou-vert","qty":250,"unit":"g","note":"kale"},{"id":"noix","qty":25,"unit":"g"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"beurre","qty":25,"unit":"g"},{"id":"huile-olive","qty":15,"unit":"ml"},{"id":"citron","qty":1,"unit":"piece"},{"id":"creme-fraiche","qty":40,"unit":"ml"},{"id":"ciboulette","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez la patate douce et le céleri en cubes 18 min à la vapeur. Écrasez-les à la fourchette avec 15 g de beurre, salez.","Faites revenir l’ail émincé dans l’huile 1 min, ajoutez le kale effeuillé et 2 cuillères d’eau, faites sauter 5 min à feu vif. Ajoutez les noix concassées et le zeste du citron.","Salez les filets de truite et cuisez-les côté peau dans le reste de beurre 4 min à feu moyen-vif, puis 1 min côté chair : la peau doit être croustillante.","Mélangez la crème, la ciboulette ciselée et le jus d’un demi-citron.","Servez la truite sur l’écrasé avec le kale et la sauce."],"tags":["rapide","riche en protéines","sans gluten"],"seasons":["automne","hiver"],"technique":"poele","flavors":["iode","herbace","cremeux"]},{"id":"dl-cabillaud-croute-graines-artichauts-fenouil","name":"Cabillaud en croûte d’herbes et graines de courge, fenouil et artichauts braisés, riz complet","description":"Dos de cabillaud sous une croûte croustillante de persil, graines de courge et parmesan, posé sur un fenouil et des cœurs d’artichaut braisés au vin blanc et citron.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":35,"difficulty":"facile","servings":2,"ingredients":[{"id":"cabillaud","qty":2,"unit":"piece","note":"dos de 170 g"},{"id":"graines-courge","qty":30,"unit":"g"},{"id":"persil","qty":20,"unit":"g"},{"id":"parmesan","qty":25,"unit":"g"},{"id":"panure","qty":15,"unit":"g"},{"id":"fenouil","qty":1,"unit":"piece"},{"id":"artichaut","qty":2,"unit":"piece","note":"cœurs, ou 250 g surgelés"},{"id":"vin-blanc","qty":80,"unit":"ml"},{"id":"citron","qty":1,"unit":"piece"},{"id":"huile-olive","qty":35,"unit":"ml"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"riz-complet","qty":120,"unit":"g"},{"id":"beurre","qty":15,"unit":"g"},{"id":"tomate-cerise","qty":8,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : faites tremper le riz complet 12 à 24 h dans de l’eau tiède, jetez l’eau et rincez avant de cuire.","Cuisez le riz complet 30 min dans 2,5 fois son volume d’eau salée.","Préchauffez le four à 200 °C. Dans une sauteuse, faites revenir le fenouil émincé et les artichauts en quartiers dans 20 ml d’huile 5 min, ajoutez l’ail, le vin blanc et le jus d’un demi-citron, couvrez et cuisez 15 min à feu doux.","Mixez grossièrement les graines de courge, le persil, le parmesan, la chapelure, le zeste du citron et 15 ml d’huile pour obtenir une chapelure verte.","Transférez les légumes dans un plat, ajoutez les tomates cerises, posez le cabillaud salé et tassez la croûte dessus. Enfournez 12 min : la chair doit s’effeuiller et la croûte dorer.","Mélangez le beurre au riz et servez avec le poisson, les légumes et un quartier de citron."],"tags":["four","riche en protéines","léger","préparation à l’avance"],"seasons":["printemps","ete"],"technique":"four","flavors":["herbace","iode","acidule"],"restTime":720},{"id":"dl-harengs-grilles-chou-pomme-kefir-seigle","name":"Harengs grillés, salade de chou-pomme au kéfir, betterave et pommes de terre à l’aneth","description":"Harengs frais grillés au beurre, salade croquante de chou, pomme et carotte au kéfir et à la moutarde, betterave rôtie et pommes de terre à l’aneth, tranche de seigle.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"nordique","prepTime":20,"cookTime":30,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"hareng","qty":4,"unit":"piece","note":"frais, vidés"},{"id":"chou-vert","qty":250,"unit":"g","note":"chou blanc émincé"},{"id":"pomme","qty":1,"unit":"piece"},{"id":"carotte","qty":1,"unit":"piece"},{"id":"kefir","qty":100,"unit":"ml"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"betterave","qty":1,"unit":"piece","note":"cuite"},{"id":"pomme-de-terre","qty":300,"unit":"g"},{"id":"aneth","qty":15,"unit":"g"},{"id":"beurre","qty":20,"unit":"g"},{"id":"farine-seigle","qty":2,"unit":"cas"},{"id":"pain-seigle","qty":2,"unit":"piece"},{"id":"vinaigre-cidre","qty":10,"unit":"ml"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez les pommes de terre 18 min à l’eau salée, égouttez et mélangez avec la moitié de l’aneth et 5 g de beurre.","Émincez finement le chou, râpez la pomme et la carotte. Mélangez avec le kéfir, la moutarde, le vinaigre et du sel. Laissez reposer 15 min pour attendrir le chou.","Coupez la betterave en quartiers, salez et poivrez.","Salez les harengs, passez-les dans la farine de seigle et cuisez-les dans le reste de beurre à feu moyen-vif 3 à 4 min par face : la peau doit être dorée et la chair se détacher de l’arête.","Servez les harengs avec la salade de chou, la betterave, les pommes de terre, le reste d’aneth et le pain de seigle."],"tags":["économique","fermenté","riche en protéines"],"seasons":["automne","hiver"],"technique":"poele","flavors":["iode","acidule","frais"]},{"id":"dl-thon-caponata-couscous-pignons","name":"Steak de thon, caponata sicilienne aux câpres et couscous aux pignons","description":"Thon frais saisi rosé sur une caponata aigre-douce d’aubergines, céleri, poivrons, olives et câpres, avec un couscous aux pignons et au basilic.","emoji":"🍆","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":20,"cookTime":35,"difficulty":"facile","servings":2,"ingredients":[{"id":"thon","qty":2,"unit":"piece"},{"id":"aubergine","qty":1,"unit":"piece"},{"id":"celeri-branche","qty":2,"unit":"piece"},{"id":"poivron-rouge","qty":1,"unit":"piece"},{"id":"oignon-rouge","qty":1,"unit":"piece"},{"id":"tomates-concassees","qty":200,"unit":"g"},{"id":"olive","qty":30,"unit":"g","note":"vertes"},{"id":"capres","qty":1,"unit":"cas"},{"id":"vinaigre-cidre","qty":20,"unit":"ml","note":"de vin rouge"},{"id":"miel","qty":1,"unit":"cac"},{"id":"huile-olive","qty":40,"unit":"ml"},{"id":"semoule","qty":100,"unit":"g"},{"id":"pignons","qty":20,"unit":"g"},{"id":"basilic","qty":15,"unit":"g"},{"id":"citron","qty":0.5,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Coupez l’aubergine en cubes de 2 cm et faites-la dorer dans 25 ml d’huile 8 min à feu moyen-vif. Réservez.","Dans la même sauteuse, faites suer l’oignon, le céleri et le poivron en dés 6 min. Ajoutez les tomates, les olives, les câpres, le vinaigre et le miel ; laissez compoter 10 min. Remettez l’aubergine 5 min.","Versez 120 ml d’eau bouillante salée sur la semoule, couvrez 5 min, égrainez avec une fourchette et ajoutez les pignons grillés et la moitié du basilic.","Salez le thon, huilez-le et saisissez-le dans une poêle fumante 1 min 30 par face : le cœur doit rester rose.","Servez le thon tranché sur la caponata tiède, avec le couscous, le reste de basilic et un trait de citron."],"tags":["riche en protéines","sportif","préparation à l’avance"],"seasons":["ete","automne"],"technique":"poele","flavors":["acidule","sucre","iode"],"tips":"La caponata est meilleure préparée la veille."},{"id":"dl-gratin-haddock-poireaux-brocoli","name":"Gratin de haddock, poireaux et brocoli au cheddar, pommes de terre","description":"Haddock fumé poché au lait, poireaux fondus et brocoli sous une sauce au lait de cuisson et au cheddar, pommes de terre en rondelles, gratiné jusqu’à dorer — iodé et riche en calcium.","emoji":"🧀","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"britannique","prepTime":25,"cookTime":40,"difficulty":"facile","servings":4,"ingredients":[{"id":"haddock","qty":500,"unit":"g"},{"id":"cabillaud","qty":300,"unit":"g","note":"dos ou lieu"},{"id":"poireau","qty":3,"unit":"piece"},{"id":"brocoli","qty":1,"unit":"piece"},{"id":"pomme-de-terre","qty":700,"unit":"g"},{"id":"lait","qty":600,"unit":"ml"},{"id":"cheddar","qty":120,"unit":"g"},{"id":"beurre","qty":40,"unit":"g"},{"id":"farine","qty":35,"unit":"g"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"persil","qty":15,"unit":"g"},{"id":"oeuf","qty":2,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Pochez le haddock et le cabillaud dans le lait avec le laurier 6 min à frémissement. Égouttez en gardant le lait, émiettez le poisson en gros morceaux.","Cuisez les pommes de terre en rondelles de 5 mm 8 min et le brocoli en fleurettes 3 min à l’eau salée. Faites fondre les poireaux émincés dans 15 g de beurre 8 min à feu doux.","Faites fondre le reste de beurre, ajoutez la farine et remuez 2 min. Versez le lait de cuisson filtré en fouettant et cuisez 5 min. Hors du feu, ajoutez la moutarde, 80 g de cheddar et le persil.","Préchauffez le four à 200 °C. Disposez poireaux, brocoli, poisson et les œufs durs (cuits 9 min) en quartiers dans un plat, nappez de sauce et couvrez de pommes de terre.","Parsemez du reste de cheddar et enfournez 25 min : les pommes de terre doivent être dorées et la sauce bouillonner."],"tags":["four","familial","réconfortant","batch cooking"],"seasons":["automne","hiver"],"technique":"four","flavors":["fume","lacte","iode"]},{"id":"dl-foie-veau-choux-bruxelles-kasha-noisettes","name":"Foie de veau poêlé, choux de Bruxelles rôtis, kasha aux noisettes et oignons confits","description":"Tranches de foie de veau rosées, choux de Bruxelles caramélisés, kasha de sarrasin aux noisettes et oignons confits au vinaigre de cidre — une assiette d’hiver exceptionnellement dense.","emoji":"🥬","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"foie-veau","qty":2,"unit":"piece"},{"id":"chou-bruxelles","qty":300,"unit":"g"},{"id":"sarrasin","qty":77,"unit":"g"},{"id":"noisette","qty":25,"unit":"g"},{"id":"oignon","qty":2,"unit":"piece"},{"id":"vinaigre-cidre","qty":20,"unit":"ml"},{"id":"beurre","qty":30,"unit":"g"},{"id":"huile-olive","qty":15,"unit":"ml"},{"id":"sauge","qty":6,"unit":"feuille"},{"id":"farine","qty":1,"unit":"cas"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"},{"id":"parmesan","qty":30,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["La veille : faites tremper la céréale 12 h (une nuit) dans de l’eau tiède additionnée d’1 c. à soupe de jus de citron ou de vinaigre de cidre. Rincez avant de cuire.","Préchauffez le four à 210 °C. Mélangez les choux coupés en deux avec l’huile et du sel, rôtissez 20 min : ils doivent être tendres et bien caramélisés.","Faites fondre les oignons émincés dans 10 g de beurre à feu doux 20 min en remuant, jusqu’à ce qu’ils soient blonds et confits. Déglacez au vinaigre.","Cuisez le sarrasin 10 min dans 2 fois son volume d’eau salée, ajoutez les noisettes torréfiées concassées et le persil.","Salez le foie et farinez-le légèrement. Faites mousser le reste de beurre avec la sauge, saisissez le foie à feu vif 1 min 30 par face : il doit rester rosé au cœur.","Servez le foie sur les oignons, avec la kasha et les choux, nappé du beurre de sauge.","Servez parsemé de parmesan râpé (son calcium limite l’absorption des oxalates)."],"tags":["abats","riche en protéines","rapide","préparation à l’avance"],"seasons":["automne","hiver"],"technique":"poele","flavors":["umami","grille","acidule"],"restTime":720}]`);export{e as default};